import boto3

def get_polly_client(region_name="us-east-1"):
    return boto3.client("polly", region_name=region_name)

def get_translate_client(region_name="us-east-1"):
    return boto3.client("translate", region_name=region_name)

def get_comprehend_client(region_name="us-east-1"):
    return boto3.client("comprehend", region_name=region_name)

def get_bedrock_runtime_client(region_name="us-east-1"):
    return boto3.client("bedrock-runtime", region_name=region_name)

def get_transcribe_client(region_name="us-east-1"):
    return boto3.client("transcribe", region_name=region_name)

def get_s3_client(region_name="us-east-1"):
    return boto3.client("s3", region_name=region_name)

from typing import Literal, Dict, Any

class SynthesizeRequest:
    text: str
    text_type: Literal["text", "ssml"]
    output_format: str
    voice_id: str
    region: str

class SynthesizeResponse:
    audio_bytes: bytes
    content_type: str

class VoiceSelectionRequest:
    language_code: str
    gender: Literal["male", "female", "any"]

class VoiceSelectionResponse:
    voices: list[Dict[str, Any]]

class SaveAudioRequest:
    audio_bytes: bytes
    file_name: str
    bucket_name: str
    content_type: str

class SaveAudioResponse:
    s3_uri: str

class TranslateRequest:
    text: str
    source_language_code: str
    target_language_code: str

class TranslateResponse:
    translated_text: str

class SafetyCheckRequest:
    text: str

class SafetyCheckResponse:
    is_safe: bool
    unsafe_categories: list[str]

class EmbeddingRequest:
    text: str

class EmbeddingResponse:
    embedding: list[float]

class TranscriptionRequest:
    audio_uri: str
    language_code: str

class TranscriptionResponse:
    transcript: str

from speech_client import get_polly_client

def synthesize_ssml(payload, config=None):
    config = config or {}
    client = get_polly_client(region_name=config.get("region"))
    response = client.synthesize_speech(Text=payload["ssml"], TextType="ssml", OutputFormat="mp3",
                                       VoiceId=config.get("voice_id", "Joanna"))
    stream = response["AudioStream"]
    try:
        return {"audio_bytes": stream.read(), "content_type": "audio/mpeg"}
    finally:
        stream.close()

from speech_client import get_polly_client

def select_voice(payload, config=None):
    config = config or {}
    client = get_polly_client(region_name=config.get("region"))
    language_code = payload.get("language_code", "en-US")
    voices = []
    paginator = client.get_paginator('describe_voices')
    for page in paginator.paginate(LanguageCode=language_code):
        voices.extend(page['Voices'])

    # Optional filtering by gender if needed by payload
    if "gender" in payload:
        gender_filter = payload["gender"].capitalize()
        voices = [voice for voice in voices if voice.get("Gender") == gender_filter]

    return {"voices": voices}

from speech_client import get_translate_client

def script_translate(payload, config=None):
    config = config or {}
    client = get_translate_client(region_name=config.get("region"))
    response = client.translate_text(
        Text=payload["text"],
        SourceLanguageCode=payload.get("source_language_code", "auto"),
        TargetLanguageCode=payload["target_language_code"]
    )
    return {"translated_text": response["TranslatedText"]}
